$ErrorActionPreference='Stop'
$entries=[Collections.Generic.Dictionary[string,string[]]]::new([StringComparer]::Ordinal)
foreach($line in Get-Content (Join-Path $PSScriptRoot 'catalog.txt')){
    if($line -eq ''){continue}
    $fields=$line.Split('|')
    if($fields.Count -ne 5 -or @($fields|Where-Object{$_ -eq ''}).Count){throw "Expected five nonempty translations: $line"}
    if($entries.ContainsKey($fields[0])){throw "Duplicate translation key: $($fields[0])"}
    $placeholders=@([regex]::Matches($fields[0],'%[1-9]')|ForEach-Object Value|Sort-Object)
    foreach($value in $fields){if((@([regex]::Matches($value,'%[1-9]')|ForEach-Object Value|Sort-Object) -join ',') -ne ($placeholders -join ',')){throw "Placeholder mismatch: $line"}}
    $entries.Add($fields[0],$fields)
}
$keys=[string[]]@($entries.Keys);[Array]::Sort($keys,[StringComparer]::Ordinal)
function QuoteCpp([string]$Value){'"'+$Value.Replace('\','\\').Replace('"','\"')+'"'}
$output=@('// SPDX-License-Identifier: GPL-2.0-or-later','// Generated by translations/generate.ps1. Edit catalog.txt, not this file.','#pragma once','#include <algorithm>','#include <atomic>','#include <cstring>','namespace mapper_i18n {','enum class Language : unsigned { Spanish, English, German, French, Italian };','inline std::atomic<Language> current{Language::English};','inline Language language(const char *locale) {','    if(!locale || !locale[0] || !locale[1]) return Language::English;','    auto lower=[](char c){return c >= ''A'' && c <= ''Z'' ? char(c+32) : c;};','    const char a=lower(locale[0]),b=lower(locale[1]);','    if(locale[2] && locale[2]!=''-'' && locale[2]!=''_'') return Language::English;','    if(a==''e'' && b==''s'') return Language::Spanish;','    if(a==''d'' && b==''e'') return Language::German;','    if(a==''f'' && b==''r'') return Language::French;','    if(a==''i'' && b==''t'') return Language::Italian;','    return Language::English;','}','inline void set_locale(const char *locale) { current.store(language(locale),std::memory_order_relaxed); }','struct Entry { const char *values[5]; };','inline constexpr Entry entries[] = {')
foreach($key in $keys){$output+='    {{'+(@($entries[$key]|ForEach-Object{QuoteCpp $_}) -join ',')+'}},'}
$output+=@('};','inline const char *text(const char *key) {','    const auto found=std::lower_bound(std::begin(entries),std::end(entries),key,[](const Entry &entry,const char *value){return std::strcmp(entry.values[0],value)<0;});','    return found!=std::end(entries) && std::strcmp(found->values[0],key)==0 ? found->values[unsigned(current.load(std::memory_order_relaxed))] : key;','}','} // namespace mapper_i18n')
Set-Content (Join-Path (Split-Path $PSScriptRoot) 'src\i18n.hpp') $output -Encoding utf8
$languages=@('spanish','english','german','french','italian');$messages=@()
foreach($line in Get-Content (Join-Path $PSScriptRoot 'installer.txt')){
    $fields=$line.Split('|');if($fields.Count -ne 6){throw 'Expected five installer translations'}
    for($index=0;$index -lt 5;$index++){$messages+=$languages[$index]+'.'+$fields[0]+'='+$fields[$index+1]}
}
Set-Content (Join-Path (Split-Path $PSScriptRoot) 'installer\messages.iss') $messages -Encoding utf8
"Generated $($entries.Count) entries in five languages"
